import asyncio

manifest = await yuki_workspace_read({"path": "/workspace/manifest.txt"})
files = [l.strip() for l in manifest["data"]["text"].splitlines() if l.strip()]

recs = {}
dup = 0
for f in files:
    r = await yuki_workspace_read({"path": "/workspace/" + f})
    for line in r["data"]["text"].splitlines()[1:]:
        if not line.strip():
            continue
        p = line.split(",")
        if p[0] in recs:
            dup += 1
            assert recs[p[0]] == (p[1], p[2], p[3])
        else:
            recs[p[0]] = (p[1], p[2], p[3])

sums = {"A": 0, "B": 0, "C": 0, "D": 0}
cnts = {"A": 0, "B": 0, "C": 0, "D": 0}
for rid, (region, amt, status) in recs.items():
    if status == "ok":
        sums[region] = sums[region] + int(amt)
        cnts[region] = cnts[region] + 1

ok_total = 0
for v in sums.values():
    ok_total = ok_total + v
print("unique ids:", len(recs), "dups:", dup)
print("per-region ok count:", cnts)
print("per-region ok sum :", sums)
print("ok count total:", cnts["A"]+cnts["B"]+cnts["C"]+cnts["D"], "sum total:", ok_total)

import asyncio

def parse_node(txt):
    kv = {}
    for line in txt.splitlines():
        line = line.strip()
        if '=' in line:
            k, v = line.split('=', 1)
            kv[k.strip()] = v.strip()
    return kv

start_r = await yuki_workspace_read({'path': '/workspace/start.txt'})
res = {'stage': 'init'}
problem = None
chain = []
notes = []
if not (start_r.get('ok') and isinstance(start_r.get('data'), dict)):
    problem = {'stage': 'start_read', 'receipt': start_r}
else:
    path = start_r['data']['text'].strip()
    idx = 0
    guard = 0
    while path and guard < 600:
        guard += 1
        nr = await yuki_workspace_read({'path': '/workspace/' + path})
        if not (nr.get('ok') and isinstance(nr.get('data'), dict) and isinstance(nr['data'].get('text'), str)):
            problem = {'stage': 'read_node', 'path': path, 'receipt': nr}
            break
        kv = parse_node(nr['data']['text'])
        if 'value' not in kv:
            problem = {'stage': 'parse_node', 'path': path, 'raw': nr['data']['text']}
            break
        value = int(kv['value'])
        chain.append([path, value])
        aname = 'audit/' + ('0' + str(idx) if idx < 10 else str(idx)) + '.txt'
        expected = str(value) + '\n'
        existing = await yuki_workspace_read({'path': '/workspace/' + aname})
        etxt = None
        if existing.get('ok') and isinstance(existing.get('data'), dict):
            etxt = existing['data'].get('text')
        if etxt is not None:
            if etxt == expected:
                notes.append([aname, 'already-correct'])
            else:
                problem = {'stage': 'audit_mismatch', 'audit': aname, 'found': etxt, 'expected': expected}
                break
        else:
            wr = await yuki_workspace_write({'path': '/workspace/' + aname, 'text': expected})
            if not wr.get('ok'):
                problem = {'stage': 'audit_write', 'audit': aname, 'receipt': wr}
                break
            notes.append([aname, 'written'])
        idx += 1
        nxt = kv.get('left') if value % 2 == 0 else kv.get('right')
        if nxt is None or nxt == '' or nxt.upper() == 'END':
            path = None
            break
        path = nxt

if problem is not None:
    res = {'problem': problem, 'chain_so_far': chain, 'audits_so_far': notes}
else:
    total = 0
    for p, v in chain:
        total += v
    lines = []
    for p, v in chain:
        lines.append(p + '\t' + str(v))
    lines.append('TOTAL\t' + str(total))
    content = '\n'.join(lines) + '\n'
    cw = await yuki_workspace_write({'path': '/workspace/chain.tsv', 'text': content})
    if not cw.get('ok'):
        ex = await yuki_workspace_read({'path': '/workspace/chain.tsv'})
        ver = None
        if ex.get('ok') and isinstance(ex.get('data'), dict):
            ver = ex['data'].get('version')
        if ver:
            cw = await yuki_workspace_write({'path': '/workspace/chain.tsv', 'text': content, 'expected_version': ver})
    rb = await yuki_workspace_read({'path': '/workspace/chain.tsv'})
    rbtext = None
    if rb.get('ok') and isinstance(rb.get('data'), dict):
        rbtext = rb['data'].get('text')
    res = {'nodes': len(chain), 'total': total, 'audits': notes,
           'chain_write_ok': cw.get('ok'), 'readback_match': rbtext == content,
           'readback': rbtext, 'lines': lines, 'problem': None}
